#!/usr/bin/env bash
# Deploy the SBIQ Conditions Evaluator stack to AWS.
# Usage: ./infra/deploy.sh [dev|prod]

set -euo pipefail

STAGE="${1:-dev}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"

cd "$SCRIPT_DIR"

echo "=== Deploying SbiqConditionsStack-$STAGE ==="

# Derive repo name for auto-generated project names
REPO_NAME=$(basename "$REPO_ROOT" | tr '[:upper:]' '[:lower:]' | tr '_' '-')

# Create venv if needed
if [[ ! -d .venv ]]; then
    python3 -m venv .venv
fi
# shellcheck disable=SC1091
source .venv/bin/activate
pip install -q -r requirements.txt

# Load .env if present (Python parse — bash `read` can drop trailing keys)
if [[ -f "$REPO_ROOT/.env" ]]; then
    eval "$(
        python3 - "$REPO_ROOT/.env" <<'PY'
import pathlib, shlex, sys
path = pathlib.Path(sys.argv[1])
for line in path.read_text().splitlines():
    line = line.strip()
    if not line or line.startswith("#") or "=" not in line:
        continue
    key, value = line.split("=", 1)
    key = key.strip()
    if not key:
        continue
    print(f"export {key}={shlex.quote(value)}")
PY
    )"
fi

# Auto-generate defaults if not set in .env and save them back
ENV_FILE="$REPO_ROOT/.env"
GENERATED_VARS=()

# Stage-specific client keys (Lambda still reads API_KEY from that stage's secret).
# Do not reuse a shared API_KEY for dev — that would keep both stacks on one key.
STAGE_API_KEY_VAR="API_KEY_$(echo "$STAGE" | tr '[:lower:]' '[:upper:]')"
STAGE_API_KEY_VAL="${!STAGE_API_KEY_VAR:-}"
if [[ -n "$STAGE_API_KEY_VAL" ]]; then
    export API_KEY="$STAGE_API_KEY_VAL"
elif [[ "$STAGE" == "prod" && -n "${API_KEY:-}" ]]; then
    GENERATED_VARS+=("API_KEY_PROD=$API_KEY")
    echo "Persisting existing API_KEY as API_KEY_PROD"
else
    export API_KEY=$(openssl rand -hex 32)
    GENERATED_VARS+=("${STAGE_API_KEY_VAR}=$API_KEY")
    echo "Auto-generated ${STAGE_API_KEY_VAR}"
fi
if [[ -z "${LANGSMITH_DEV_PROJECT:-}" ]]; then
    export LANGSMITH_DEV_PROJECT="${REPO_NAME}-dev"
    GENERATED_VARS+=("LANGSMITH_DEV_PROJECT=$LANGSMITH_DEV_PROJECT")
    echo "Auto-generated LANGSMITH_DEV_PROJECT: $LANGSMITH_DEV_PROJECT"
fi
if [[ -z "${LANGSMITH_PROD_PROJECT:-}" ]]; then
    export LANGSMITH_PROD_PROJECT="${REPO_NAME}-prod"
    GENERATED_VARS+=("LANGSMITH_PROD_PROJECT=$LANGSMITH_PROD_PROJECT")
    echo "Auto-generated LANGSMITH_PROD_PROJECT: $LANGSMITH_PROD_PROJECT"
fi
if [[ -z "${CORS_ALLOW_ORIGINS:-}" ]]; then
    export CORS_ALLOW_ORIGINS="*"
    GENERATED_VARS+=("CORS_ALLOW_ORIGINS=$CORS_ALLOW_ORIGINS")
fi

# Append auto-generated values to .env so they persist (MCI playbook latest)
if [[ ${#GENERATED_VARS[@]} -gt 0 ]]; then
    touch "$ENV_FILE"
    echo "" >> "$ENV_FILE"
    echo "# Auto-generated by deploy.sh on $(date +%Y-%m-%d)" >> "$ENV_FILE"
    for var in "${GENERATED_VARS[@]}"; do
        echo "$var" >> "$ENV_FILE"
    done
    echo "Saved ${#GENERATED_VARS[@]} auto-generated values to .env"
fi

# Warn about required external credentials
if [[ -z "${LANGSMITH_API_KEY:-}" ]]; then
    echo "⚠️  WARNING: LANGSMITH_API_KEY not set — tracing will be disabled"
    echo "   Get it from: https://smith.langchain.com → Settings → API Keys"
fi
if [[ -z "${ANTHROPIC_API_KEY:-}" ]]; then
    echo "⚠️  WARNING: ANTHROPIC_API_KEY not set — agent will fail at runtime"
fi

export STAGE="$STAGE"
export SBIQ_AWS_REGION="${SBIQ_AWS_REGION:-${AWS_DEFAULT_REGION:-us-east-2}}"
AWS_REGION="$SBIQ_AWS_REGION"
export AWS_REGION
export AWS_DEFAULT_REGION="$AWS_REGION"

# Bootstrap if needed
cdk bootstrap --app "python3 app.py" 2>/dev/null || true

# Deploy
cdk deploy "SbiqConditionsStack-$STAGE" \
    --app "python3 app.py" \
    --require-approval never \
    --outputs-file "../output-$STAGE.json"

echo "=== Deployment complete ==="
echo "Outputs saved to output-$STAGE.json"

# Get outputs
API_URL=$(jq -r ".\"SbiqConditionsStack-$STAGE\".ApiUrl // empty" "../output-$STAGE.json" 2>/dev/null || echo "")
SECRETS_ARN=$(jq -r ".\"SbiqConditionsStack-$STAGE\".AgentSecretsArn // empty" "../output-$STAGE.json" 2>/dev/null || echo "")

# Push secrets to Secrets Manager
if [[ -n "$SECRETS_ARN" ]]; then
    echo "=== Pushing secrets to Secrets Manager ==="

    if [[ "$STAGE" == "prod" ]]; then
        LANGSMITH_PROJECT="${LANGSMITH_PROD_PROJECT:-}"
    else
        LANGSMITH_PROJECT="${LANGSMITH_DEV_PROJECT:-}"
    fi

    # Do not replace a live model key. Seed it only when the secret has none.
    LIVE_ANTHROPIC="$(aws secretsmanager get-secret-value \
        --secret-id "$SECRETS_ARN" \
        --query SecretString --output text \
        --region "$AWS_REGION" 2>/dev/null \
        | jq -r '.ANTHROPIC_API_KEY // empty' || true)"
    if [[ -n "$LIVE_ANTHROPIC" ]]; then
        echo "ANTHROPIC_API_KEY already set; leaving it unchanged."
        ANTHROPIC_API_KEY="$LIVE_ANTHROPIC"
    fi

    SECRETS_JSON=$(jq -n \
        --arg api_key "${API_KEY:-}" \
        --arg anthropic_key "${ANTHROPIC_API_KEY:-}" \
        --arg anthropic_model "${ANTHROPIC_MODEL:-}" \
        --arg langsmith_key "${LANGSMITH_API_KEY:-}" \
        --arg langchain_key "${LANGCHAIN_API_KEY:-${LANGSMITH_API_KEY:-}}" \
        --arg langsmith_project "$LANGSMITH_PROJECT" \
        '{
            "API_KEY": $api_key,
            "ANTHROPIC_API_KEY": $anthropic_key,
            "ANTHROPIC_MODEL": $anthropic_model,
            "LANGSMITH_API_KEY": $langsmith_key,
            "LANGCHAIN_API_KEY": $langchain_key,
            "LANGSMITH_PROJECT": $langsmith_project
        }')

    aws secretsmanager put-secret-value \
        --secret-id "$SECRETS_ARN" \
        --secret-string "$SECRETS_JSON" \
        --region "$AWS_REGION"

    echo "Secrets pushed successfully"

    echo "=== Verifying secrets ==="
    aws secretsmanager get-secret-value \
        --secret-id "$SECRETS_ARN" \
        --query SecretString --output text \
        --region "$AWS_REGION" \
        | python3 -c "import json,sys; [print(f'  {k}: {\"SET\" if v else \"EMPTY\"}') for k,v in json.load(sys.stdin).items()]"
fi

if [[ -n "$API_URL" ]]; then
    echo ""
    echo "=== API URL ==="
    echo "$API_URL"
fi
